```openscad
// Bench rack for 32 x 0.5 mL microcentrifuge tubes
// Print orientation: block base on XY plane at z = 0, holes open upward (+Z)

// ---------------- Parameters ----------------
block_len   = 104;   // block length along X (mm)
block_wid   = 56;    // block width along Y (mm)
block_h     = 30;    // block height along Z (mm)

cols        = 8;     // holes per row (along X)
rows        = 4;     // number of rows (along Y)
pitch_x     = 12;    // centre-to-centre spacing along X (mm)
pitch_y     = 12;    // centre-to-centre spacing along Y (mm)

hole_d      = 8.0;   // hole diameter (mm)
hole_depth  = 24;    // hole depth from top face (mm)
floor_t     = block_h - hole_depth; // solid floor thickness (= 6 mm)

overcut     = 0.5;   // extension of cutters past top face (mm)
$fn         = 64;    // resolution for curved surfaces

// Grid offsets so the hole pattern is centred on the block
x0 = -(cols - 1) * pitch_x / 2;
y0 = -(rows - 1) * pitch_y / 2;

// ---------------- Model ----------------
difference() {
    // Solid block, centred in X/Y, resting on z = 0
    translate([-block_len / 2, -block_wid / 2, 0])
        cube([block_len, block_wid, block_h]);

    // 4 x 8 grid of blind tube holes
    for (i = [0 : cols - 1])
        for (j = [0 : rows - 1])
            translate([x0 + i * pitch_x, y0 + j * pitch_y, floor_t])
                cylinder(d = hole_d, h = hole_depth + overcut, $fn = 64);
}
```

