// Snap-on C-clip for 12.0 mm lab-stand rod
// Printed flat: 2-D profile in XY, extruded along +Z

// ---- Parameters ----
rod_d      = 12.0;               // inner diameter (rod diameter)
wall       = 4.0;                // ring wall thickness
outer_d    = rod_d + 2*wall;     // outer diameter = 20.0
clip_h     = 12.0;               // extrusion height (Z)
gap_w      = 8.4;                // opening width (y from -4.2 to 4.2)
eps        = 0.5;                // overshoot for clean cuts
$fn        = 128;                // circle resolution

// ---- Model ----
linear_extrude(height = clip_h)
    difference() {
        circle(d = outer_d);
        // bore
        circle(d = rod_d);
        // opening on -X side: x < 0, -gap_w/2 < y < gap_w/2
        translate([-(outer_d/2 + eps), -gap_w/2])
            square([outer_d/2 + eps, gap_w]);
    }
```

```openscad
// Two-part enclosure: box + lid (lid printed upside down), side by side on the bed

// ---------- Box ----------
box_x     = 80;    // box outer length (X)
box_y     = 40;    // box outer width (Y)
box_z     = 25;    // box outer height (Z)
wall      = 2.5;   // box wall thickness
floor_t   = 2.0;   // box floor thickness

// ---------- Lid ----------
lid_x     = 80;    // lid plate length (X)
lid_y     = 40;    // lid plate width (Y)
lid_t     = 2.0;   // lid plate thickness
lip_x     = 74.4;  // lip outer length (X), 0.3 mm clearance per side
lip_y     = 34.4;  // lip outer width (Y), 0.3 mm clearance per side
lip_wall  = 1.5;   // lip wall thickness
lip_h     = 4;     // lip height above plate

// ---------- Layout ----------
gap       = 10;    // gap between parts on the bed
eps       = 0.5;   // overshoot for clean boolean cuts
$fn       = 64;

// Centres so the pair is centred on the origin in X
box_cx = -(gap / 2 + box_x / 2);
lid_cx =  (gap / 2 + lid_x / 2);

// ---------- Part 1: box (open top) ----------
module box() {
    difference() {
        translate([-box_x / 2, -box_y / 2, 0])
            cube([box_x, box_y, box_z]);
        translate([-(box_x - 2 * wall) / 2, -(box_y - 2 * wall) / 2, floor_t])
            cube([box_x - 2 * wall, box_y - 2 * wall, box_z - floor_t + eps]);
    }
}

// ---------- Part 2: lid (upside down, lip pointing up) ----------
module lid() {
    union() {
        translate([-lid_x / 2, -lid_y / 2, 0])
            cube([lid_x, lid_y, lid_t]);
        difference() {
            translate([-lip_x / 2, -lip_y / 2, lid_t - 0.01])
                cube([lip_x, lip_y, lip_h + 0.01]);
            translate([-(lip_x - 2 * lip_wall) / 2, -(lip_y - 2 * lip_wall) / 2, lid_t - eps / 2])
                cube([lip_x - 2 * lip_wall, lip_y - 2 * lip_wall, lip_h + eps]);
        }
    }
}

translate([box_cx, 0, 0]) box();
translate([lid_cx, 0, 0]) lid();
