```openscad
// Push-on cap for a 20.0 mm OD tube, printed open-end up
$fn = 96;

// --- Dimensions ---
cap_od        = 25.8;   // outer diameter of cap
cap_h         = 14.0;   // total height
bore_d        = 20.8;   // blind bore diameter (20.0 tube + 0.8 diametral clearance)
floor_t       = 3.0;    // closed cap thickness at bottom
groove_n      = 12;     // number of grip grooves
groove_d      = 2.0;    // grip groove diameter (half-cylinder centred on outer surface)
eps           = 0.5;    // overshoot for clean cuts

difference() {
    // Main body
    cylinder(d = cap_od, h = cap_h);

    // Blind bore from top
    translate([0, 0, floor_t])
        cylinder(d = bore_d, h = cap_h - floor_t + eps);

    // Vertical grip grooves, full height
    for (i = [0 : groove_n - 1])
        rotate([0, 0, i * 360 / groove_n])
            translate([cap_od / 2, 0, -eps])
                cylinder(d = groove_d, h = cap_h + 2 * eps, $fn = 48);
}
