```openscad
// Replacement control knob for 6.0 mm D-shaft
// Print orientation: hotplate-facing (shaft) side down on the bed

// ---------------- Parameters ----------------
knob_d        = 30.0;  // knob outer diameter
knob_h        = 14.0;  // knob total height

bore_d        = 6.2;   // D-bore circle diameter (clearance for 6.0 mm shaft)
bore_flat     = 4.7;   // distance from flat to opposite side of bore circle
bore_depth    = 9.0;   // blind bore depth from bottom face

groove_n      = 14;    // number of grip grooves
groove_d      = 2.0;   // grip groove diameter (half-cylinder on outer surface)

eps           = 0.5;   // overshoot for clean boolean cuts
$fn           = 96;    // circle resolution

// Derived
knob_r        = knob_d / 2;
bore_r        = bore_d / 2;
flat_offset   = bore_flat - bore_r;   // flat position from bore centre (+X side)

// ---------------- Modules ----------------
module d_profile() {
    intersection() {
        circle(r = bore_r, $fn = 64);
        // keep everything from the far side of the circle up to the flat
        translate([-bore_r - 1, -bore_r - 1])
            square([flat_offset + bore_r + 1, bore_d + 2]);
    }
}

// ---------------- Model ----------------
difference() {
    // Knob body
    cylinder(d = knob_d, h = knob_h);

    // D-shaped blind bore from the bottom face
    translate([0, 0, -eps])
        linear_extrude(height = bore_depth + eps)
            d_profile();

    // Vertical grip grooves, centred on the outer surface
    for (i = [0 : groove_n - 1])
        rotate([0, 0, i * 360 / groove_n])
            translate([knob_r, 0, -eps])
                cylinder(d = groove_d, h = knob_h + 2 * eps, $fn = 48);
}
