```openscad
// Weighted base for a vertical support rod - printed upright
$fn = 96;

// --- Base disc ---
disc_d      = 90.0;   // disc diameter
disc_h      = 10.0;   // disc thickness (z = 0 to 10)

// --- Central boss ---
boss_d      = 28.0;   // boss diameter
boss_top_z  = 40.0;   // top of boss

// --- Rod bore ---
bore_d      = 12.0;   // blind bore diameter
bore_bot_z  = 10.0;   // bore floor height

// --- Set-screw hole ---
screw_d     = 5.0;    // radial set-screw hole diameter
screw_z     = 34.0;   // height of set-screw axis

eps         = 0.5;    // overlap for clean cuts

difference() {
    union() {
        // Base disc
        cylinder(d = disc_d, h = disc_h);
        // Boss, overlapping slightly into disc for a clean union
        translate([0, 0, disc_h - eps])
            cylinder(d = boss_d, h = boss_top_z - disc_h + eps);
    }

    // Blind bore from top of boss down to z = 10
    translate([0, 0, bore_bot_z])
        cylinder(d = bore_d, h = boss_top_z - bore_bot_z + eps);

    // Radial set-screw hole from +X outer face into the bore
    translate([0, 0, screw_z])
        rotate([0, 90, 0])
            cylinder(d = screw_d, h = boss_d / 2 + eps);
}
