// L-shaped mounting bracket
// Print orientation: base plate flat on the bed (z = 0), vertical plate rising at y = 0

$fn = 64;

// ---------- Base plate ----------
base_x_min   = -28;   // base plate X start
base_x_max   = 28;    // base plate X end
base_y_min   = 0;     // base plate Y start (back edge)
base_y_max   = 35;    // base plate Y end (front edge)
base_thick   = 4;     // base plate thickness (Z)

// ---------- Vertical plate ----------
vert_x_min   = -28;   // vertical plate X start
vert_x_max   = 28;    // vertical plate X end
vert_y_min   = 0;     // vertical plate Y start
vert_thick   = 4;     // vertical plate thickness (Y)
vert_height  = 40;    // vertical plate height (Z)

// ---------- Holes ----------
hole_d       = 6.5;   // through-hole diameter (both plates)
base_hole_y  = 20;    // Y position of base plate holes
base_hole_xs = [-20, 20];  // X positions of base plate holes
vert_hole_z  = 25;    // Z position of vertical plate holes
vert_hole_xs = [-20, 20];  // X positions of vertical plate holes

eps          = 0.5;   // cutter overshoot past faces

difference() {
    union() {
        // Base plate
        translate([base_x_min, base_y_min, 0])
            cube([base_x_max - base_x_min, base_y_max - base_y_min, base_thick]);

        // Vertical plate
        translate([vert_x_min, vert_y_min, 0])
            cube([vert_x_max - vert_x_min, vert_thick, vert_height]);
    }

    // Vertical through-holes in base plate (along Z)
    for (x = base_hole_xs)
        translate([x, base_hole_y, -eps])
            cylinder(d = hole_d, h = base_thick + 2 * eps);

    // Horizontal through-holes in vertical plate (along Y)
    for (x = vert_hole_xs)
        translate([x, vert_y_min - eps, vert_hole_z])
            rotate([-90, 0, 0])
                cylinder(d = hole_d, h = vert_thick + 2 * eps);
}
