```openscad
// 8-well agarose gel comb, printed flat (plate lies on XY, thickness in Z)

// ---------------- Parameters ----------------
spine_len    = 46.0;   // spine (back bar) length, X
spine_wid    = 12.0;   // spine width, Y
thickness    = 2.0;    // plate thickness, Z
n_teeth      = 8;      // number of teeth / wells
tooth_w      = 3.0;    // tooth width, X
tooth_l      = 8.0;    // tooth length, Y (hanging in -Y)
tooth_gap    = 2.0;    // gap between neighbouring teeth, X
overlap      = 0.01;   // small overlap so teeth fuse with spine

// ---------------- Derived ----------------
row_w     = n_teeth * tooth_w + (n_teeth - 1) * tooth_gap;  // total width of tooth row (38 mm)
total_y   = spine_wid + tooth_l;                            // overall Y extent
y_bottom  = -total_y / 2;                                   // tooth tips
y_spine0  = y_bottom + tooth_l;                             // spine lower edge
x_start   = -row_w / 2;                                     // first tooth left edge

// ---------------- Model ----------------
union() {
    // Spine
    translate([-spine_len / 2, y_spine0, 0])
        cube([spine_len, spine_wid, thickness]);

    // Teeth
    for (i = [0 : n_teeth - 1])
        translate([x_start + i * (tooth_w + tooth_gap), y_bottom, 0])
            cube([tooth_w, tooth_l + overlap, thickness]);
}
