// Rigid in-line rod coupler - printed upright along Z
$fn = 96;

outer_d     = 20.0;   // coupler outer diameter
length      = 25.0;   // coupler length (Z)
bore_d      = 3.0;    // axial bore diameter
screw_d     = 4.5;    // radial set-screw hole diameter
screw_pos   = [0.25, 0.75]; // set-screw positions as fraction of length
eps         = 0.5;    // cut overshoot past faces

difference() {
    // main body
    cylinder(d = outer_d, h = length);

    // axial bore through full length
    translate([0, 0, -eps])
        cylinder(d = bore_d, h = length + 2 * eps);

    // radial set-screw holes on +X side (from bore centre out through wall)
    for (f = screw_pos)
        translate([0, 0, f * length])
            rotate([0, 90, 0])
                cylinder(d = screw_d, h = outer_d / 2 + eps);
}
