```openscad
// Small lab funnel, printed upright (wide opening up)
$fn = 128;

// ---- Dimensions (mm) ----
spout_od   = 8.0;    // spout outer diameter
spout_h    = 25.0;   // spout height (z = 0 .. 25)
rim_od     = 40.0;   // cone outer diameter at rim
total_h    = 50.0;   // rim height
wall       = 1.6;    // wall thickness (normal to surface)
eps        = 1.0;    // overcut for clean differences

// ---- Derived ----
r_sp   = spout_od / 2;                 // 4.0
r_rim  = rim_od / 2;                   // 20.0
cone_h = total_h - spout_h;            // 25.0
k      = (r_rim - r_sp) / cone_h;      // radial slope dr/dz
sec_a  = sqrt(1 + k * k);              // 1/cos(cone half-angle)
r_bore = r_sp - wall;                  // 2.4 spout bore radius

// inner cone surface: offset perpendicular by 'wall'
r_in0  = r_sp - wall * sec_a;          // inner radius on cone line at z = spout_h
z_join = spout_h + (r_bore - r_in0) / k; // where inner cone meets bore
r_in_top = r_in0 + k * (total_h + eps - spout_h); // inner radius just above rim

module outer_profile() {
    polygon([
        [0, 0],
        [r_sp, 0],
        [r_sp, spout_h],
        [r_rim, total_h],
        [0, total_h]
    ]);
}

module inner_profile() {
    polygon([
        [0, -eps],
        [r_bore, -eps],
        [r_bore, z_join],
        [r_in_top, total_h + eps],
        [0, total_h + eps]
    ]);
}

difference() {
    rotate_extrude() outer_profile();
    rotate_extrude() inner_profile();
}
