```openscad
// Flat drilling/marking jig with 4x4 hole grid and orientation notch
// Units: mm. Print orientation: plate flat on bed, z = 0 to plate_t.

$fn = 64;

// ---- Plate ----
plate_x = 58;     // plate length (X)
plate_y = 58;     // plate width (Y)
plate_t = 6;      // plate thickness (Z)

// ---- Hole grid ----
hole_d     = 5.0; // through-hole diameter
hole_nx    = 4;   // holes along X
hole_ny    = 4;   // holes along Y
hole_pitch = 12;  // centre-to-centre spacing (both directions)

// ---- Orientation notch (+Y edge, centred on Y axis) ----
notch_w = 12;     // notch width (X)
notch_d = 3;      // notch depth (Y, in from +Y edge)

// ---- Cutting overshoot ----
eps = 0.5;        // extension past cut faces to avoid coplanar faces

difference() {
    // Main plate, centred in XY
    translate([-plate_x/2, -plate_y/2, 0])
        cube([plate_x, plate_y, plate_t]);

    // 4 x 4 grid of through-holes, centred on the plate
    for (i = [0 : hole_nx - 1])
        for (j = [0 : hole_ny - 1])
            translate([(i - (hole_nx - 1)/2) * hole_pitch,
                       (j - (hole_ny - 1)/2) * hole_pitch,
                       -eps])
                cylinder(d = hole_d, h = plate_t + 2*eps);

    // Rectangular orientation notch in +Y edge
    translate([-notch_w/2, plate_y/2 - notch_d, -eps])
        cube([notch_w, notch_d + eps, plate_t + 2*eps]);
}
```

