```openscad
// Snap-on C-clip for a 12.7 mm lab-stand rod
// Print orientation: flat, profile in XY, extruded along +Z from z = 0

$fn = 128;

// ---------------- Parameters ----------------
rod_d      = 12.7;              // rod diameter = ring inner diameter (mm)
wall_t     = 3.0;               // ring wall thickness (mm)
outer_d    = rod_d + 2*wall_t;  // ring outer diameter = 18.7 mm
clip_h     = 15;                // extrusion height along Z (mm)
opening_w  = 8.9;               // width of the snap opening on the -X side (mm)

eps        = 0.5;               // overshoot for clean boolean cuts (mm)

// ---------------- Derived ----------------
r_in  = rod_d / 2;
r_out = outer_d / 2;

// ---------------- Model ----------------
difference() {
    // Ring
    difference() {
        cylinder(h = clip_h, r = r_out);
        translate([0, 0, -eps])
            cylinder(h = clip_h + 2*eps, r = r_in);
    }

    // Opening: remove everything with x < 0 and |y| < opening_w/2
    translate([-(r_out + eps), -opening_w/2, -eps])
        cube([r_out + eps, opening_w, clip_h + 2*eps]);
}
```

```openscad
// Two-part enclosure: open-top box + upside-down lid, printed side by side
// Units: mm

$fn = 64;

// ---------- Box ----------
box_x     = 90;    // box outer length (X)
box_y     = 40;    // box outer width (Y)
box_z     = 30;    // box outer height (Z)
wall      = 1.6;   // box side wall thickness
floor_t   = 2.0;   // box floor thickness

// ---------- Lid ----------
lid_x     = 90;    // lid plate length (X)
lid_y     = 40;    // lid plate width (Y)
lid_t     = 3.0;   // lid plate thickness
lip_x     = 86.2;  // lip outer length (X)
lip_y     = 36.2;  // lip outer width (Y)
lip_wall  = 2.0;   // lip wall thickness
lip_h     = 3.0;   // lip height above plate

// ---------- Layout ----------
gap       = 10;    // gap between box and lid on the bed
eps       = 0.5;   // cutter overshoot past faces

// Centre the pair of parts on the origin in X
total_x   = box_x + gap + lid_x;
box_cx    = -total_x/2 + box_x/2;          // box centre X
lid_cx    =  total_x/2 - lid_x/2;          // lid centre X (+X side)

// ---------- Modules ----------
module box() {
    difference() {
        translate([-box_x/2, -box_y/2, 0])
            cube([box_x, box_y, box_z]);
        // inner cavity, open top
        translate([-(box_x - 2*wall)/2, -(box_y - 2*wall)/2, floor_t])
            cube([box_x - 2*wall, box_y - 2*wall, box_z - floor_t + eps]);
    }
}

module lid() {
    union() {
        // plate lying on the bed
        translate([-lid_x/2, -lid_y/2, 0])
            cube([lid_x, lid_y, lid_t]);
        // rectangular lip on top of the plate
        difference() {
            translate([-lip_x/2, -lip_y/2, lid_t - 0.01])
                cube([lip_x, lip_y, lip_h + 0.01]);
            translate([-(lip_x - 2*lip_wall)/2, -(lip_y - 2*lip_wall)/2, lid_t - eps])
                cube([lip_x - 2*lip_wall, lip_y - 2*lip_wall, lip_h + 2*eps]);
        }
    }
}

// ---------- Assembly on the bed ----------
translate([box_cx, 0, 0]) box();
translate([lid_cx, 0, 0]) lid();
