// Small lab funnel - printed upright, wide opening at the top
// Built as a single rotate_extrude of a 2D wall profile (open top and bottom)

$fn = 128;

// ---------------- Dimensions (mm) ----------------
spout_od     = 14.0;   // spout outer diameter
spout_top_z  = 18.0;   // spout runs from z=0 to this height
rim_od       = 70.0;   // cone outer diameter at the rim
rim_z        = 43.0;   // height of the rim (top of funnel)
wall         = 1.6;    // wall thickness (normal to the surface)

// ---------------- Derived values ----------------
spout_or = spout_od / 2;                  // 7.0  spout outer radius
spout_ir = spout_or - wall;               // 5.4  spout inner radius (10.8 bore)
rim_or   = rim_od / 2;                    // 35.0 rim outer radius
cone_h   = rim_z - spout_top_z;           // 25.0 cone height
k        = (rim_or - spout_or) / cone_h;  // radial growth per mm of height
ro       = wall * sqrt(1 + k * k);        // radial offset giving 1.6 mm normal wall on cone
rim_ir   = rim_or - ro;                   // inner radius at the rim
z_join   = spout_top_z + (ro - wall) / k; // where inner cone meets the spout bore

// ---------------- Wall profile (r, z) ----------------
profile = [
    [spout_or, 0],            // outer bottom of spout
    [spout_or, spout_top_z],  // outer spout/cone transition
    [rim_or,   rim_z],        // outer rim
    [rim_ir,   rim_z],        // inner rim
    [spout_ir, z_join],       // inner cone/bore transition
    [spout_ir, 0]             // inner bottom of spout
];

// ---------------- Model ----------------
rotate_extrude(convexity = 4)
    polygon(points = profile);
