// Small lab funnel, printed upright with the wide opening at the top
// All dimensions in mm

$fn = 96;

// ---- Parameters ----
spout_od     = 8.0;    // spout outer diameter
spout_h      = 22.0;   // spout height (z = 0 .. 22)
rim_od       = 50.0;   // cone outer diameter at the rim
rim_z        = 57.0;   // rim height
wall         = 2.4;    // wall thickness, measured perpendicular to the wall
eps          = 1.0;    // how far cutters extend past the faces they cut

// ---- Derived values ----
spout_r   = spout_od / 2;               // 4.0
bore_r    = spout_r - wall;             // 1.6 (3.2 mm bore)
rim_r     = rim_od / 2;                 // 25.0
cone_h    = rim_z - spout_h;            // 35.0
slope     = (rim_r - spout_r) / cone_h; // dr/dz of the cone wall (0.6)
h_off     = wall * sqrt(1 + slope*slope); // horizontal offset that gives 2.4 mm perpendicular wall

// The inner cone surface is r_in(z) = spout_r + slope*(z - spout_h) - h_off.
// It meets the spout bore (r = bore_r) at z = join_z.
join_z    = spout_h + (bore_r - spout_r + h_off) / slope;
top_cut_z = rim_z + eps;                // inner cone runs past the rim
in_r_top  = spout_r + slope*(top_cut_z - spout_h) - h_off;

// ---- Model ----
difference() {
    // Outer body
    union() {
        cylinder(h = spout_h, r = spout_r);                   // spout
        translate([0, 0, spout_h])
            cylinder(h = cone_h, r1 = spout_r, r2 = rim_r);   // cone
    }

    // Spout bore, running out through the bottom
    translate([0, 0, -eps])
        cylinder(h = join_z + eps + 0.01, r = bore_r);

    // Inner cone, running out through the rim
    translate([0, 0, join_z])
        cylinder(h = top_cut_z - join_z, r1 = bore_r, r2 = in_r_top);
}
