    translate([0, 0, -eps])
        cylinder(d = bore_d, h = length + 2 * eps);

    // Radial set-screw holes on +X side, from axis out through the wall
    for (z = setscrew_zs)
        translate([0, 0, z])
            rotate([0, 90, 0])
                cylinder(d = setscrew_d, h = outer_d / 2 + eps);
