// Small lab funnel - printed upright, wide opening at top
// Built as a single rotate_extrude of a wall profile (open top and bottom)

$fn = 128;

// ---- Dimensions (mm) ----
spout_od     = 8.0;    // spout outer diameter
spout_len    = 20;     // spout runs z = 0 .. 20
rim_od       = 40;     // cone outer diameter at rim
rim_z        = 50;     // rim height (top of funnel)
wall         = 1.2;    // wall thickness (normal to surface)

// ---- Derived ----
r_spout_o = spout_od / 2;               // 4.0
r_spout_i = r_spout_o - wall;           // 2.8 (5.6 mm bore)
r_rim_o   = rim_od / 2;                 // 20.0
cone_h    = rim_z - spout_len;          // 30
k         = (r_rim_o - r_spout_o) / cone_h;   // radial slope dr/dz
h_off     = wall * sqrt(1 + k * k);     // horizontal offset giving 1.2 mm normal wall on cone
r_rim_i   = r_rim_o - h_off;            // inner radius at rim
// z where the inner cone surface meets the spout bore
z_join    = spout_len + (h_off - wall) / k;

// ---- Profile (r, z) revolved about Z ----
module funnel_profile() {
    polygon(points = [
        [r_spout_i, 0],          // bottom inner
        [r_spout_o, 0],          // bottom outer
        [r_spout_o, spout_len],  // spout/cone transition outer
        [r_rim_o,   rim_z],      // rim outer
        [r_rim_i,   rim_z],      // rim inner
        [r_spout_i, z_join]      // cone/bore transition inner
    ]);
}

rotate_extrude(convexity = 4)
    funnel_profile();
```

