// Flat drilling/marking jig - 3x3 hole grid with orientation notch
// Units: mm. Print orientation: flat on bed, z = 0 up to plate_t.

// ---------------- Parameters ----------------
plate_l      = 38.0;   // plate length (X)
plate_w      = 38.0;   // plate width (Y)
plate_t      = 3.0;    // plate thickness (Z)

hole_d       = 6.0;    // through-hole diameter
hole_pitch   = 8.0;    // centre-to-centre spacing (X and Y)
hole_nx      = 3;      // holes along X
hole_ny      = 3;      // holes along Y

notch_w      = 10.0;   // orientation notch width (X)
notch_d      = 3.0;    // orientation notch depth (Y, in from +Y edge)

eps          = 0.5;    // cutter overshoot past faces
$fn          = 96;     // curve resolution

// ---------------- Model ----------------
difference() {
    // Base plate, centred in X/Y, resting on z = 0
    translate([-plate_l / 2, -plate_w / 2, 0])
        cube([plate_l, plate_w, plate_t]);

    // 3 x 3 grid of through-holes, centred on the plate
    for (i = [0 : hole_nx - 1])
        for (j = [0 : hole_ny - 1])
            translate([(i - (hole_nx - 1) / 2) * hole_pitch,
                       (j - (hole_ny - 1) / 2) * hole_pitch,
                       -eps])
                cylinder(d = hole_d, h = plate_t + 2 * eps);

    // Rectangular orientation notch in the +Y edge, centred on Y axis
    translate([-notch_w / 2, plate_w / 2 - notch_d, -eps])
        cube([notch_w, notch_d + eps, plate_t + 2 * eps]);
}
