// Two-part enclosure: open-top box + upside-down lid with sliding lip
// Both parts printed side by side, lid on +X side, 10 mm gap.

$fn = 64;

// ---------- Box parameters ----------
box_x      = 90.0;   // box outer length (X)
box_y      = 50.0;   // box outer width (Y)
box_z      = 25.0;   // box outer height (Z)
wall_t     = 2.0;    // box side wall thickness
floor_t    = 2.5;    // box floor thickness

// ---------- Lid parameters ----------
lid_x      = 90.0;   // lid plate length (X)
lid_y      = 50.0;   // lid plate width (Y)
lid_t      = 2.5;    // lid plate thickness
lip_x      = 85.6;   // lip outer length (0.2 mm clearance per side in 86 mm opening)
lip_y      = 45.6;   // lip outer width (0.2 mm clearance per side in 46 mm opening)
lip_t      = 1.5;    // lip wall thickness
lip_h      = 5.0;    // lip height above plate

// ---------- Layout ----------
gap        = 10.0;   // gap between the two parts on the bed
eps        = 0.5;    // cutter overrun past faces
ovl        = 0.01;   // small overlap for unions

// Centre the pair on the origin in X: total length = box_x + gap + lid_x
total_x    = box_x + gap + lid_x;
box_cx     = -total_x/2 + box_x/2;          // box centre X
lid_cx     =  total_x/2 - lid_x/2;          // lid centre X (+X side)

// ---------- Part 1: Box ----------
module box() {
    difference() {
        translate([-box_x/2, -box_y/2, 0])
            cube([box_x, box_y, box_z]);
        // inner cavity, open top
        translate([-(box_x - 2*wall_t)/2, -(box_y - 2*wall_t)/2, floor_t])
            cube([box_x - 2*wall_t, box_y - 2*wall_t, box_z - floor_t + eps]);
    }
}

// ---------- Part 2: Lid (upside down) ----------
module lid() {
    union() {
        // plate on the bed
        translate([-lid_x/2, -lid_y/2, 0])
            cube([lid_x, lid_y, lid_t]);
        // rectangular lip wall
        difference() {
            translate([-lip_x/2, -lip_y/2, lid_t - ovl])
                cube([lip_x, lip_y, lip_h + ovl]);
            translate([-(lip_x - 2*lip_t)/2, -(lip_y - 2*lip_t)/2, lid_t - eps])
                cube([lip_x - 2*lip_t, lip_y - 2*lip_t, lip_h + 2*eps]);
        }
    }
}

// ---------- Assembly on bed ----------
translate([box_cx, 0, 0]) box();
translate([lid_cx, 0, 0]) lid();
