// Replacement control knob for 6.3 mm D-shaft
// Print orientation: hotplate-facing side (bore opening) down on the bed

// ---------- Dimensions ----------
knob_d        = 25.0;   // knob outer diameter
knob_h        = 18.0;   // knob total height

bore_d        = 6.5;    // D-bore circle diameter
bore_flat     = 5.0;    // distance from flat to opposite side of circle
bore_depth    = 14.0;   // blind bore depth from bottom face

groove_count  = 16;     // number of vertical grip grooves
groove_d      = 2.0;    // groove (half-cylinder) diameter, centred on outer surface

eps           = 0.5;    // cutter overshoot past faces
$fn           = 96;     // curve resolution

// Derived
flat_offset   = bore_flat - bore_d / 2;   // flat position from bore centre (1.75 mm)

// ---------- D-shaped bore cutter ----------
module d_bore() {
    translate([0, 0, -eps])
        linear_extrude(height = bore_depth + eps)
            intersection() {
                circle(d = bore_d, $fn = 96);
                // keep everything on the round side of the flat
                translate([-bore_d, -bore_d])
                    square([bore_d + flat_offset, 2 * bore_d]);
            }
}

// ---------- Knob ----------
difference() {
    cylinder(d = knob_d, h = knob_h, $fn = 128);

    // D-shaft bore
    d_bore();

    // Grip grooves along full height
    for (i = [0 : groove_count - 1])
        rotate([0, 0, i * 360 / groove_count])
            translate([knob_d / 2, 0, -eps])
                cylinder(d = groove_d, h = knob_h + 2 * eps, $fn = 48);
}
